		"colleagues.createDialog.rolePreset.frontend": "前端开发工程师",
		"colleagues.createDialog.rolePreset.frontendDesc": "负责前端界面设计与实现，擅长组件架构、交互细节、响应式适配和性能优化，保障体验稳定。持续沉淀最佳实践。",
		"colleagues.createDialog.rolePreset.seniorDeveloper": "高级开发工程师",
		"colleagues.createDialog.rolePreset.seniorDeveloperDesc": "负责复杂模块设计与技术攻坚，擅长架构权衡、性能优化、高并发处理和疑难问题定位，保障高质量交付。持续沉淀技术方案。",
		"colleagues.createDialog.rolePreset.wechatMiniProgram": "微信小程序开发员",
		"colleagues.createDialog.rolePreset.wechatMiniProgramDesc": "负责微信小程序开发框架和生态，体验优化，保障流畅稳定。持续沉淀小程序实践经验，打造流畅微信原生体验应用",
		"colleagues.createDialog.rolePreset.mobile": "移动端开发工程师",
		"colleagues.createDialog.rolePreset.mobileDesc": "负责 iOS、Android 与跨端应用开发，擅长交互实现、性能优化、兼容适配和发布质量保障。持续沉淀移动端实践。",
		"colleagues.createDialog.rolePreset.aiEngineer": "AI工程师",
		"colleagues.createDialog.rolePreset.aiEngineerDesc": "负责大模型应用与智能体开发，擅长 RAG、提示工程、流程编排和效果调优，推动 AI 能力落地业务。持续沉淀工程实践。",
		"colleagues.createDialog.rolePreset.projectManager": "项目经理",
		"colleagues.createDialog.rolePreset.projectManagerDesc": "负责计划排期、资源协调和风险管理，擅长跨团队推进、进度跟踪和按期交付保障。持续同步里程碑、风险和资源变化。",
		"colleagues.createDialog.rolePreset.ui": "UI设计师",
		"colleagues.createDialog.rolePreset.uiDesc": "负责界面视觉、组件规范和设计交付，擅长布局、色彩、图标和细节打磨，提升产品质感。持续沉淀规范，保障体验一致。",
		"colleagues.createDialog.rolePreset.qa": "工程测试员",
		"colleagues.createDialog.rolePreset.qaDesc": "负责测试方案、用例设计和缺陷跟踪，擅长自动化验证、风险识别和上线质量保障。持续沉淀测试资产，提升交付信心。",
		"colleagues.createDialog.rolePreset.backendArchitect": "后端架构师",
		"colleagues.createDialog.rolePreset.backendArchitectDesc": "负责服务端架构与系统设计，擅长高并发、高可用、分层解耦和性能调优，保障系统稳定可扩展。持续沉淀架构方案。",
		"colleagues.createDialog.rolePreset.productAdmin": "产品管理员",
		"colleagues.createDialog.rolePreset.productAdminDesc": "负责计划排期、资源协调和风险管理，擅长跨团队推进、进度跟踪和按期交付保障。持续同步里程碑、风险和资源变化。",
		"colleagues.createDialog.rolePreset.xiaohongshuOperator": "小红书运营专员",
		"colleagues.createDialog.rolePreset.xiaohongshuOperatorDesc": "负责小红书内容运营与增长，擅长选题策划、爆款标题，深谙小红书种草生态和推荐机制，打造高互动率种草内容，持续沉淀运营方法。",
		"colleagues.createDialog.rolePreset.contentCreator": "内容创作专员",
		"colleagues.createDialog.rolePreset.contentCreatorDesc": "负责内容策划与创作产出，擅长选题挖掘、图文脚本、文案撰写和质量把控，提升传播效果。持续沉淀创作方法。",
		"colleagues.createDialog.rolePreset.stockResearcher": "股票研究员",
		"colleagues.createDialog.rolePreset.stockResearcherDesc": "负责个股研究与行情跟踪，擅长财报解读、估值分析、行业逻辑梳理和风险研判，输出客观研究结论。持续沉淀研究框架。",
		"colleagues.createDialog.rolePreset.industryResearcher": "行业研究员",
		"colleagues.createDialog.rolePreset.industryResearcherDesc": "负责行业研究与趋势分析，擅长政策解读、竞争格局梳理、数据验证和洞察提炼，支撑业务决策。持续沉淀研究方法。",
		"colleagues.createDialog.rolePreset.dataAnalyst": "数据分析员",
		"colleagues.createDialog.rolePreset.dataAnalystDesc": "负责指标体系、数据看板和专题分析，擅长发现业务问题、验证假设并输出清晰决策建议。持续沉淀分析方法，推动业务增长。",
		"colleagues.createDialog.rolePreset.experienceArchitect": "体验架构师",
		"colleagues.createDialog.rolePreset.experienceArchitectDesc": "负责体验策略、信息架构和交互框架，擅长流程梳理、复杂场景拆解和一致性建设，化繁为简提升体验。持续沉淀体验规范。",
		"colleagues.createDialog.rolePreset.webDeveloper": "Web开发工程师",
		"colleagues.createDialog.rolePreset.webDeveloperDesc": "负责 Web 应用前后端开发，擅长页面实现、接口对接、性能优化和兼容适配，保障交付效率与体验。持续沉淀工程实践。",
		"colleagues.createDialog.rolePreset.softwareArchitect": "软件架构师",
		"colleagues.createDialog.rolePreset.softwareArchitectDesc": "负责系统架构与技术选型，擅长分层解耦、扩展性设计、稳定性建设和技术决策，保障系统可维护可生长。持续沉淀架构资产。",
		"colleagues.createDialog.rolePreset.codeReviewer": "代码审查员",
		"colleagues.createDialog.rolePreset.codeReviewerDesc": "负责代码评审与质量把关，擅长规范检查、性能审视、隐患识别和改进建议，保障代码健康。持续沉淀评审规范，提升协作效率。",
		"colleagues.createDialog.rolePreset.gameDesigner": "游戏设计师",
		"colleagues.createDialog.rolePreset.gameDesignerDesc": "负责玩法设计、数值平衡和关卡规划，擅长核心循环搭建、体验调优和系统打磨，提升可玩性与留存。持续沉淀设计方法。",
		"colleagues.createDialog.rolePreset.docGenerator": "文档生成员",
		"colleagues.createDialog.rolePreset.docGeneratorDesc": "负责技术文档、接入指南和知识沉淀，擅长结构化表达、示例编写和版本同步。持续沉淀写作规范，提升协作效率。",
