		"automation.templates.dailyWords.title": "每日 5 个英语单词",
		"automation.templates.dailyWords.content": "每天推荐 5 个高频实用英语单词，包含词义、音标、例句与记忆提示。",
		"automation.templates.bedtimeStory.title": "每日儿童睡前故事",
		"automation.templates.bedtimeStory.content": "生成 3-5 分钟可读的温和睡前故事，情节完整并附简短寓意。",
		"automation.templates.weeklyReport.title": "每周工作周报",
		"automation.templates.weeklyReport.content": "每周五汇总仓库 PR 与 Issue 进展，输出关键变更与待关注事项。",
		"automation.templates.classicMovie.title": "经典电影推荐",
		"automation.templates.classicMovie.content": "推荐一部高分经典电影，简要介绍剧情梗概、亮点与推荐理由，全程不剧透。",
		"automation.templates.historyToday.title": "历史上的今天",
		"automation.templates.historyToday.content": "从科技、电影、音乐等领域挑选一件\"今天发生过\"的有趣事件，200-300 字讲清来龙去脉。",
		"automation.templates.dailyWhy.title": "每日一个为什么",
		"automation.templates.dailyWhy.content": "每天抛出一个有趣问题，先提问再解答，语气轻松、通俗易懂，答案控制在 200-300 字。",
		"automation.templates.cutePetWallpaper.title": "可爱萌宠手机壁纸",
		"automation.templates.cutePetWallpaper.content": "随机从 7 种不同风格中挑选一种，为你生成一张 9:16 竖版高清萌宠手机壁纸。",
		"automation.templates.parentContactReminder.title": "父母联系提醒",
		"automation.templates.parentContactReminder.content": "每周日 10:00 提醒你给家人打电话或发消息，简单问候近况。",
		"automation.templates.healthCheckupReminder.title": "体检预约提醒",
		"automation.templates.healthCheckupReminder.content": "在 2026/04/08 07:00 提醒你确认体检时间、准备证件，并注意空腹与其他事项。",
		"automation.templates.interviewPreparationReminder.title": "面试准备提醒",
		"automation.templates.interviewPreparationReminder.content": "工作日每 2 小时提醒你复习大模型面试内容，并生成 3 个模拟问题。",
		"automation.templates.preMeetingPreparation.title": "会议前准备",
		"automation.templates.preMeetingPreparation.content": "在会议开始前提醒你整理议题、目标、待确认问题和关键结论。",
		"automation.templates.dailyAiNews.prompt": "关注当天 AI 领域的重要动态，侧重 AI coding 与具身智能方向。筛选 3-5 条有价值的信息，简要说明事件内容及值得关注的原因。",
		"automation.templates.dailyWords.prompt": "每天推荐 5 个实用英语单词，优先选取生活和职场中常见词汇。输出词义、音标、例句，以及一条便于记忆的小提示。",
		"automation.templates.bedtimeStory.prompt": "写一个适合儿童的睡前故事，语言温和易懂，阅读时长约 3-5 分钟。故事需有完整情节，结尾附上简短寓意。",
		"automation.templates.weeklyReport.prompt": "梳理本周仓库中的 PR 与 Issue 情况，包括新增、已关闭及重点讨论。输出一份周报，涵盖主要进展、关键变更和待关注事项。",
		"automation.templates.classicMovie.prompt": "给我推荐一部公认的经典电影（评分高、口碑好），简要介绍剧情梗概、亮点所在，以及它为什么值得一看，但是不要剧透。",
		"automation.templates.historyToday.prompt": "历史上的今天发生过什么有趣的事？从科技、电影、音乐等领域中挑一个，讲讲它的来龙去脉吧。控制在 200-300 字左右。",
		"automation.templates.dailyWhy.prompt": "随机挑选一个有趣的冷知识或生活百科问题，并给出详细、有趣、通俗易懂的解答。每次问题尽量不重复，覆盖科学、生活、历史、自然、食物、文化、动物、人体等多个领域；先抛出问题再揭晓答案；语气轻松有趣；答案控制在 200-300 字。",
		"automation.templates.parentContactReminder.prompt": "每周日十点提醒我给家人打电话或发消息，简单问候近况。",
		"automation.templates.healthCheckupReminder.prompt": "4月8号七点提醒我确认体检时间、准备证件，提前空腹并留意注意事项。",
		"automation.templates.interviewPreparationReminder.prompt": "每两小时提醒我复习关于大模型的项目亮点、技术难点、常见问答，并生成 3 个模拟面试问题。",
		"automation.templates.preMeetingPreparation.prompt": "在会议开始前，提醒我整理议题、目标、需要确认的问题，以及要同步的关键结论。",
		"automation.templates.cutePetWallpaper.prompt": "帮我生成一张手机壁纸，以下主题随机选一个就可以。\n主体：可爱萌宠。格式要求：手机壁纸、高清分辨率，size:576x1024，9:16 竖版比例。\n主题 1：毛绒绒云朵主题，精美边框，创意排版，漫画浪漫主义，复杂华丽，漂浮云朵元素，薄荷绿与天空蓝主色调，温柔可爱。\n主题 2：模糊感与笔触感结合的极简精致插画，深邃宝石蓝背景，超现实主义美学，层次丰富，光影与反射形成视觉张力，同时保持和谐高级感。\n主题 3：武政谅风格卡通手机壁纸，丝网印刷艺术风格，细腻颗粒肌理，柔和胶版印刷质感，极简纯扁平插画，主体为猫咪，高饱和多巴胺色系。\n主题 4：虚拟电子风格，体素块构成，乱码与数字故障纹理，轻微失真星环，全息炫彩半透明水晶质感，随机色彩断层与扫描线，高饱和克莱因蓝背景，蜜桃粉点缀。\n主题 5：精致绘本插画风格，线条简洁流畅，高级米色单色调与大面积留白，略仰视角，淡雅水彩渲染，精致可爱且有童趣。\n主题 6：复古主义风格，花卉布局错落有致，极繁细致，以自然柔和色系为主，线条勾勒清晰，高饱和色彩呈现华丽质感。\n主题 7：随手乱画的极简风，幼稚滑稽，潦草手绘，形象失真，稚拙可爱，同时带一点梦境、故事感与治愈氛围。\n请只选择其中一个主题来创作，不要混用多个主题。",
